    def test_runtime_assert_for_prim(self):
        # [FUNCTION DOC] Checks runtime guards on non-tensor inputs: with a dynamic
        #   first dim and an int input the module accepts equal ints and raises a
        #   guard failure for a different int; the same for a float input.
        class Foo(torch.nn.Module):
            # [CLASS DOC] HELPER: Module adding two inputs.
            def forward(self, x, y):
                # [FUNCTION DOC] HELPER: Returns x plus y.
                return x + y

        foo = Foo()
        tensor_inp = torch.ones(7, 5)
        dim0_x = torch.export.Dim("dim0_x", min=6)
        dynamic_shapes = {"x": {0: dim0_x}, "y": None}
        exported = torch.export.export(
            foo, (tensor_inp, 5), dynamic_shapes=dynamic_shapes
        )
        self.assertTrue(
            torch.allclose(
                exported.module()(torch.ones(8, 5), 5), foo(torch.ones(8, 5), 5)
            )
        )
        with self.assertRaisesRegex(
            AssertionError,
            escape("Guard failed: y == 5"),
        ):
            # expected 5, but got 6
            _ = exported.module()(torch.ones(8, 5), 6)

        exported = torch.export.export(
            foo, (tensor_inp, 5.0), dynamic_shapes=dynamic_shapes
        )
        with self.assertRaisesRegex(
            AssertionError,
            escape("Guard failed: y == 5.0"),
        ):
            # expected 5.0, but got 6.0
            _ = exported.module()(torch.ones(7, 5), 6.0)

